INSERT INTO public.songs(id,title,artist,year,lane,primary_lane,sub_lane,active,movement,atmosphere,immersion,scale,community,perspective,confidence,tension,texture,transformation,canon_score,routing_power,diagnostic_power,primary_dimensions,polarization,tradeoff_richness,pairing_density,identity_signaling,longevity,cross_genre_mapping,scoring_version,scored_at,scoring_provenance,rationale)
INSERT INTO pack_pairs VALUES
(md5('musicdna:decade-pack-2026-11-11:pair:D1970-002')::uuid,'2a095f3d-af48-4201-9030-d2fe6a092113'::uuid,'9d5742dc-22a1-4371-94d7-f39eaf99ba67'::uuid,ARRAY['tension', 'movement', 'transformation']::text[],'Urgent threat against quiet, resigned loss. Dolly Parton leans toward danger; Willie Nelson leans toward release.','Beg the redhead to back off, or cry quietly in the rain?','country'),
(md5('musicdna:decade-pack-2026-11-11:pair:D1970-003')::uuid,md5('musicdna:decade-pack-2026-11-11:song:merle_haggard__if_we_make_it_through_december')::uuid,'6a123a07-0b15-92ba-7ef9-d09edf48ea28'::uuid,ARRAY['community', 'scale', 'tension']::text[],'A private struggle against a mass singalong homecoming. Merle Haggard leans toward solitary; John Denver leans toward communal.','Just get through the winter, or sing the whole road home?','country'),
(md5('musicdna:decade-pack-2026-11-11:pair:D1970-004')::uuid,md5('musicdna:decade-pack-2026-11-11:song:freddy_fender__before_the_next_teardrop_falls')::uuid,'1c1d9456-b2fa-530f-9cb1-615d5b6cb431'::uuid,ARRAY['movement', 'tension', 'perspective']::text[],'Measured lament against a racing fiddle contest. Freddy Fender leans toward stillness; The Charlie Daniels Band leans toward forward motion.','A slow tear in two languages, or a fiddle duel with the devil?','country'),
(md5('musicdna:decade-pack-2026-11-11:pair:D1970-005')::uuid,'6f84923e-817f-4de8-953b-1646a680e99d'::uuid,md5('musicdna:decade-pack-2026-11-11:song:chic__le_freak')::uuid,ARRAY['atmosphere', 'immersion', 'transformation']::text[],'Hypnotic synthetic immersion against direct group celebration. Donna Summer leans toward immersive mood; Chic leans toward statement.','Float inside Moroder''s machine, or yell ''Freak out!'' with the room?','disco'),
(md5('musicdna:decade-pack-2026-11-11:pair:D1970-007')::uuid,'e3aec23f-9f5a-b072-be6a-a53076e39f0d'::uuid,'3a67f3eb-b431-acd2-0662-ab01ae7a89ff'::uuid,ARRAY['tension', 'confidence']::text[],'Joyful arrival against emotional desperation. ABBA leans toward release; Thelma Houston leans toward danger.','Seventeen and dancing free, or begging someone not to leave?','disco'),
(md5('musicdna:decade-pack-2026-11-11:pair:D1970-008')::uuid,'9172ef0f-1bc1-0023-013a-03eaeaa6e935'::uuid,'ded88d8c-d4fe-647d-3cf8-e204444cd112'::uuid,ARRAY['immersion', 'atmosphere', 'confidence']::text[],'An immediate dance demand against a long slow-burn opening. The Trammps leans toward immediacy; Diana Ross leans toward slow reveal.','Burn the disco down, or melt into Diana''s slow hangover?','disco'),
(md5('musicdna:decade-pack-2026-11-11:pair:D1970-010')::uuid,'af27a1e2-e146-4feb-a88a-14a3afb06ea1'::uuid,md5('musicdna:decade-pack-2026-11-11:song:the_staple_singers__respect_yourself')::uuid,ARRAY['confidence', 'atmosphere', 'immersion']::text[],'Searching social witness against direct self-affirming command. Marvin Gaye leans toward vulnerability; The Staple Singers leans toward command.','Ask what''s going on, or tell them to respect themselves?','r_and_b'),
(md5('musicdna:decade-pack-2026-11-11:pair:D1970-011')::uuid,'e810169e-8ba1-191e-1746-a15a7cbfa145'::uuid,md5('musicdna:decade-pack-2026-11-11:song:labelle__lady_marmalade')::uuid,ARRAY['scale', 'community', 'immersion']::text[],'Close sensual address against bold stage-sized expression. Marvin Gaye leans toward intimate; Labelle leans toward vast.','One bedroom and Marvin, or a French invitation to the whole street?','r_and_b'),
(md5('musicdna:decade-pack-2026-11-11:pair:D1970-012')::uuid,md5('musicdna:decade-pack-2026-11-11:song:aerosmith__dream_on')::uuid,md5('musicdna:decade-pack-2026-11-11:song:thin_lizzy__the_boys_are_back_in_town')::uuid,ARRAY['immersion', 'transformation', 'movement']::text[],'Long dramatic build against instant riff-led payoff. Aerosmith leans toward slow reveal; Thin Lizzy leans toward immediacy.','Wait for Tyler''s scream to build, or the boys bursting through the door?','classic_rock'),
(md5('musicdna:decade-pack-2026-11-11:pair:D1970-013')::uuid,md5('musicdna:decade-pack-2026-11-11:song:pink_floyd__the_great_gig_in_the_sky')::uuid,md5('musicdna:decade-pack-2026-11-11:song:dire_straits__sultans_of_swing')::uuid,ARRAY['atmosphere', 'perspective', 'immersion']::text[],'Wordless emotional atmosphere against clearly narrated musicianship. Pink Floyd leans toward immersive mood; Dire Straits leans toward statement.','A wordless wail at the edge of life, or a tight band you can watch?','classic_rock'),
(md5('musicdna:decade-pack-2026-11-11:pair:D1970-014')::uuid,'99a4f4b1-cfeb-4e08-b0b0-75dd072a86be'::uuid,md5('musicdna:decade-pack-2026-11-11:song:fleetwood_mac__rhiannon')::uuid,ARRAY['community', 'atmosphere', 'tension']::text[],'Anthemic place identity against shadowy personal fascination. Lynyrd Skynyrd leans toward communal; Fleetwood Mac leans toward solitary.','Sing along about Alabama, or follow the witch into the night?','classic_rock'),
(md5('musicdna:decade-pack-2026-11-11:pair:D1970-015')::uuid,md5('musicdna:decade-pack-2026-11-11:song:james_brown__get_up_i_feel_like_being_a_sex_machine')::uuid,md5('musicdna:decade-pack-2026-11-11:song:parliament__flash_light')::uuid,ARRAY['texture', 'atmosphere', 'immersion']::text[],'Rough-edged live rhythmic command against sculpted space-funk production. James Brown leans toward rawness; Parliament leans toward refinement.','James Brown''s sweat on the floor, or Parliament''s spaceship funk?','r_and_b'),
(md5('musicdna:decade-pack-2026-11-11:pair:D1970-016')::uuid,'c77b1fa8-f6f3-9a49-b9a9-6093e2cac7a0'::uuid,'e0947584-3cde-4d0f-8bec-9c2e0796cb1e'::uuid,ARRAY['scale', 'perspective', 'immersion']::text[],'Public alarm against intimate disorientation. The Clash leans toward vast; Talking Heads leans toward intimate.','The river''s flooding the city, or one nervous guy''s head?','alternative'),
(md5('musicdna:decade-pack-2026-11-11:pair:D1980-017')::uuid,md5('musicdna:decade-pack-2026-11-11:song:george_strait__amarillo_by_morning')::uuid,'8edc812d-4a4a-4059-82d8-12eec44add9a'::uuid,ARRAY['community', 'confidence', 'movement']::text[],'Solitary endurance against a collective workday anthem. George Strait leans toward solitary; Dolly Parton leans toward communal.','Alone on the highway at dawn, or the whole office walking out at five?','country'),
