(md5('musicdna:decade-pack-2026-11-11:pair:D2010-080')::uuid,'fbcfd6ab-c742-1c20-906e-015c4fc4698b'::uuid,md5('musicdna:decade-pack-2026-11-11:song:architects__doomsday')::uuid,ARRAY['texture']::text[],'Ornate dramatic polish against rough physical attack. Ghost leans toward refinement; Architects leans toward rawness.','Ghost''s polished cathedral, or Architects'' raw grief?','metal'),
(md5('musicdna:decade-pack-2026-11-11:pair:D2020-081')::uuid,'07948700-1fd4-4161-986a-6e9eaed1e649'::uuid,'155714a6-9c05-48f6-a616-8ceb4c57d7d1'::uuid,ARRAY['confidence', 'texture', 'immersion']::text[],'Fragile unresolved ache against assertive commercial cool. Zach Bryan leans toward vulnerability; Morgan Wallen leans toward command.','Zach Bryan grieving in the orange, or Wallen''s loud last night?','country'),
(md5('musicdna:decade-pack-2026-11-11:pair:D2020-082')::uuid,'fd88dc78-9801-0fdc-c65b-c4b05bcb8ca3'::uuid,'cb81de99-b1f4-44be-8e32-c6b1543d2566'::uuid,ARRAY['movement', 'texture', 'atmosphere']::text[],'Urgent gallop against contemplative stillness. Chris Stapleton leans toward forward motion; Kacey Musgraves leans toward stillness.','Chris Stapleton running off, or Kacey Musgraves still asking who designed this?','country'),
(md5('musicdna:decade-pack-2026-11-11:pair:D2020-083')::uuid,'bdd75b1d-699b-ae36-b7c0-fe99e0171175'::uuid,md5('musicdna:decade-pack-2026-11-11:song:zach_bryan__pink_skies')::uuid,ARRAY['community', 'confidence', 'movement']::text[],'Public celebration against quiet personal mourning. Shaboozey leans toward communal; Zach Bryan leans toward solitary.','The whole bar singing ''Tipsy'', or Zach Bryan alone under pink skies?','country'),
(md5('musicdna:decade-pack-2026-11-11:pair:D2020-084')::uuid,md5('musicdna:decade-pack-2026-11-11:song:dasha__austin_boots_stop_workin')::uuid,md5('musicdna:decade-pack-2026-11-11:song:lainey_wilson__heart_like_a_truck')::uuid,ARRAY['movement', 'community']::text[],'Dance-forward confrontation against patient endurance. Dasha leans toward forward motion; Lainey Wilson leans toward stillness.','Line-dancing till your boots give out, or a heart that keeps on hauling?','country'),
(md5('musicdna:decade-pack-2026-11-11:pair:D2020-085')::uuid,'dc7aefa0-fc0a-4dac-80e3-f22a5ea34131'::uuid,'cf24be05-9a75-484e-b1eb-d23bb38d6d0d'::uuid,ARRAY['tension', 'perspective']::text[],'Self-possessed release against charged accusation. Miley Cyrus leans toward release; Olivia Rodrigo leans toward danger.','Buy yourself flowers, or call out the vampire?','pop'),
(md5('musicdna:decade-pack-2026-11-11:pair:D2020-088')::uuid,'1a17f1f5-d61d-cf8e-7e98-8f19883c0b32'::uuid,md5('musicdna:decade-pack-2026-11-11:song:wolf_alice__the_beach')::uuid,ARRAY['movement', 'community', 'perspective']::text[],'Driving guitar momentum against a slow atmospheric build. Sam Fender leans toward forward motion; Wolf Alice leans toward stillness.','Sam Fender''s town at full tilt, or Wolf Alice lying still on the beach?','alternative'),
(md5('musicdna:decade-pack-2026-11-11:pair:D2020-090')::uuid,'f77a1c66-af97-4291-baa2-031d6fe3033a'::uuid,'74c03ebc-820b-2bee-172d-1e06c1fb3b16'::uuid,ARRAY['scale', 'tension', 'movement']::text[],'Wide ensemble confession against close personal devotion. boygenius leans toward vast; Mitski leans toward intimate.','Boygenius admitting they''re not strong enough, or Mitski''s love beyond the stars?','alternative'),
(md5('musicdna:decade-pack-2026-11-11:pair:D2020-093')::uuid,md5('musicdna:decade-pack-2026-11-11:song:muni_long__made_for_me')::uuid,md5('musicdna:decade-pack-2026-11-11:song:ari_lennox__pressure')::uuid,ARRAY['movement', 'confidence']::text[],'Slower devotion against a sharper dance-inflected pulse. Muni Long leans toward stillness; Ari Lennox leans toward forward motion.','Muni Long''s slow wedding vow, or Ari Lennox''s thick pressure?','r_and_b'),
(md5('musicdna:decade-pack-2026-11-11:pair:D2020-094')::uuid,md5('musicdna:decade-pack-2026-11-11:song:kendrick_lamar__not_like_us')::uuid,md5('musicdna:decade-pack-2026-11-11:song:kodak_black__super_gremlin')::uuid,ARRAY['community', 'scale', 'movement']::text[],'Collective chant against paranoid solitary address. Kendrick Lamar leans toward communal; Kodak Black leans toward solitary.','Kendrick and the whole crowd shouting, or Kodak alone with his gremlins?','hip_hop'),
(md5('musicdna:decade-pack-2026-11-11:pair:D2020-095')::uuid,md5('musicdna:decade-pack-2026-11-11:song:drake_and_21_savage__rich_flex')::uuid,md5('musicdna:decade-pack-2026-11-11:song:lil_uzi_vert__just_wanna_rock')::uuid,ARRAY['movement', 'transformation', 'community']::text[],'Midtempo verbal performance against almost pure kinetic drive. Drake & 21 Savage leans toward stillness; Lil Uzi Vert leans toward forward motion.','Drake and Savage''s lazy flex, or Uzi''s track that just won''t stop?','hip_hop'),
(md5('musicdna:decade-pack-2026-11-11:pair:D2020-096')::uuid,md5('musicdna:decade-pack-2026-11-11:song:megan_thee_stallion__hiss')::uuid,md5('musicdna:decade-pack-2026-11-11:song:doja_cat__paint_the_town_red')::uuid,ARRAY['texture', 'tension']::text[],'Barbed vocal attack against glossy theatrical swagger. Megan Thee Stallion leans toward rawness; Doja Cat leans toward refinement.','Megan''s raw diss, or Doja''s polished red sneer?','hip_hop'),
(md5('musicdna:decade-pack-2026-11-11:pair:D2020-097')::uuid,md5('musicdna:decade-pack-2026-11-11:song:fred_again__marea_we_ve_lost_dancing')::uuid,md5('musicdna:decade-pack-2026-11-11:song:chase_and_status_feat_bou_flowdan_trigga_and_takura__baddadan')::uuid,ARRAY['tension', 'immersion', 'confidence']::text[],'Nostalgic communal ache against high-pressure rhythmic menace. Fred again.. leans toward release; Chase & Status feat. Bou, Flowdan, Trigga & Takura leans toward danger.','Fred again.. mourning the dancefloor, or Baddadan threatening the room?','electronic'),
(md5('musicdna:decade-pack-2026-11-11:pair:D2020-098')::uuid,'5e4a6ed9-1100-9404-5e3a-8bda1055e2a5'::uuid,md5('musicdna:decade-pack-2026-11-11:song:justice_and_tame_impala__neverender')::uuid,ARRAY['texture', 'perspective', 'tension']::text[],'Grainy bass pressure against smooth melodic architecture. Skrillex, Fred again.. & Flowdan leans toward rawness; Justice & Tame Impala leans toward refinement.','Skrillex and Flowdan''s grime rumble, or Justice''s glossy loop with Tame Impala?','electronic'),
(md5('musicdna:decade-pack-2026-11-11:pair:D2020-100')::uuid,'730b0e70-d18c-41a9-8885-5c78e83e11f6'::uuid,md5('musicdna:decade-pack-2026-11-11:song:lorna_shore__to_the_hellfire')::uuid,ARRAY['texture', 'perspective', 'tension']::text[],'Highly arranged shape-shifting polish against extreme abrasive assault. Sleep Token leans toward refinement; Lorna Shore leans toward rawness.','Sleep Token''s gloss and glow, or Lorna Shore''s blackened hellfire?','metal');
