BEGIN;
SET LOCAL lock_timeout='5s';
CREATE TEMP TABLE pack_songs(k text,title text,artist text,year int,lane text,pl text,sub_lane text,v int[],canon int,routing int) ON COMMIT DROP;
DO $g$ BEGIN IF EXISTS(SELECT 1 FROM pack_songs n JOIN public.songs s ON lower(btrim(s.title))=lower(btrim(n.title)) AND lower(btrim(s.artist))=lower(btrim(n.artist)) WHERE s.id<>md5('musicdna:decade-pack-2026-11-11:song:'||n.k)::uuid) THEN RAISE EXCEPTION 'Existing song identity collision'; END IF; END $g$;
WITH calc AS (SELECT n.*, (SELECT count(*)::int FROM unnest(v) x WHERE x<=30 OR x>=70) strong,(SELECT count(*)::int FROM unnest(v) x WHERE x<35 OR x>65) nn FROM pack_songs n), metrics AS(SELECT c.*,least(25,6+strong+CASE WHEN canon<95 THEN 3 ELSE 0 END) pol,least(20,7+nn) richness,least(15,6+ceil(strong/2.0)::int) ident,CASE WHEN year<2000 THEN 10 WHEN year<=2016 THEN 8 WHEN year<=2021 THEN 5 ELSE 3 END longevity,CASE WHEN routing<80 THEN 13 ELSE 10 END crossmap FROM calc c)
SELECT md5('musicdna:decade-pack-2026-11-11:song:'||k)::uuid,title,artist,year,lane,pl,sub_lane,false,v[1],v[2],v[3],v[4],v[5],v[6],v[7],v[8],v[9],v[10],canon,routing,pol+richness+9+ident+longevity+crossmap,ARRAY(SELECT ax FROM unnest(ARRAY['movement','atmosphere','immersion','scale','community','perspective','confidence','tension','texture','transformation']) WITH ORDINALITY d(ax,i) ORDER BY abs(v[i]-50) DESC,i LIMIT 3),pol,richness,9,ident,longevity,crossmap,lane||'_editorial_v1',now(),jsonb_build_object('method','editorial_axis_estimates','listener_validated',false,'review_status','provisional','source','docs/musicdna/decade-curation-2026-11-11','existing_catalog_rescored',false),'Editorial '||replace(sub_lane,'_',' ')||' estimate from the decade curation pack; listener validation pending.' FROM metrics ON CONFLICT(id) DO NOTHING;
CREATE TEMP TABLE pack_pairs(id uuid,a uuid,b uuid,tests text[],why text,phrase text,lane text) ON COMMIT DROP;
SELECT n.id,n.a,n.b,n.tests,n.why,n.why||' Editorial contrast only; listener split not yet measured.',n.phrase,n.lane,false,86,'Unmeasured; listener validation pending',2,false FROM pack_pairs n
WHERE NOT EXISTS(SELECT 1 FROM public.pairings x WHERE least(x.song_a_id,x.song_b_id)=least(n.a,n.b) AND greatest(x.song_a_id,x.song_b_id)=greatest(n.a,n.b)) ON CONFLICT(id) DO NOTHING;
DO $a$ DECLARE sc int; pc int; detail text; BEGIN
SELECT count(*) INTO sc FROM pack_songs n JOIN public.songs s ON s.id=md5('musicdna:decade-pack-2026-11-11:song:'||n.k)::uuid;
SELECT count(*) INTO pc FROM pack_pairs n JOIN public.pairings p ON p.id=n.id;
IF sc<>84 OR pc<>75 THEN RAISE EXCEPTION 'Incomplete pack import: % songs / % pairings',sc,pc; END IF;
SELECT string_agg(p.id::text||':'||t,', ') INTO detail FROM pack_pairs n JOIN public.pairings p ON p.id=n.id JOIN public.songs sa ON sa.id=p.song_a_id JOIN public.songs sb ON sb.id=p.song_b_id CROSS JOIN LATERAL unnest(p.tests) t WHERE abs((to_jsonb(sa)->>t)::int-(to_jsonb(sb)->>t)::int)<20;
IF detail IS NOT NULL THEN RAISE EXCEPTION 'Pack test audit failed: %',detail; END IF;
END $a$;
UPDATE public.songs s SET active=true FROM pack_songs n WHERE s.id=md5('musicdna:decade-pack-2026-11-11:song:'||n.k)::uuid AND NOT s.active AND EXISTS(SELECT 1 FROM pack_pairs pp WHERE pp.a=s.id OR pp.b=s.id);
UPDATE public.pairings p SET active=true FROM pack_pairs n WHERE p.id=n.id AND NOT p.active;
COMMIT;